"""Compare saved completed v8 and historical recovery outcomes; no inference."""
import json,os
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[2]
P=ROOT/os.environ.get('EXPERIMENT_OUTPUT','results/jquery-4.0.0/minified-no-tree-shaking-mapping-v8')
OLD=ROOT/'results/jquery-4.0.0/minified-no-tree-shaking'
def read(p):return json.loads(p.read_text())
new=read(P/'summary.json');old=read(OLD/'summary.json');assert new['status']=='complete'
verify=read(P/'verification.json');assert verify['status']=='passed'
breakdown=read(P/'recovery-bottlenecks/summary.json');oldBreakdown=read(OLD/'recovery-bottlenecks/summary.json')
previous={b['build']:b for b in old['builds']};comparisons=[]
for b in new['builds']:
 a=previous[b['build']];assert b['supportedJqueryDefinitions']==a['supportedJqueryDefinitions'];assert b['anchors']==a['anchors']
 comparisons.append({'build':b['build'],'supportedFunctions':b['supportedJqueryDefinitions'],'previousCorrect':a['final']['correct'],'correct':b['final']['correct'],'previousRecoveryPercent':a['correctRecovery'],'recoveryPercent':b['correctRecovery'],'correctChange':b['final']['correct']-a['final']['correct'],'wrong':b['final']['wrong'],'unassessed':b['final']['unassessed'],'identityPrecisionPercent':b['conditionalPrecision'],'rounds':b['round'],'modelPairs':b['modelPairs'],'modelCalls':b['modelCalls'],'cacheHits':b['cacheHits'],'invalid':b['invalid'],'errors':b['errors']})
known=sum(x['supportedFunctions'] for x in comparisons);correct=sum(x['correct'] for x in comparisons);before=sum(x['previousCorrect'] for x in comparisons);wrong=sum(x['wrong'] for x in comparisons)
assert sum(breakdown['aggregate'].values())==known-correct
names={'correct_top3_but_never_accepted':'Correct top-three candidate rejected; never accepted','correct_top3_only_invalid_or_error':'Correct top-three candidate only had invalid/error responses','correct_accepted_but_multiple_positives':'Correct candidate accepted but multiple positives blocked promotion','never_queried_no_matched_neighbor':'Never queried: no matched neighbor','correct_candidate_never_top3':'Correct source available but never ranked in top three','wrong_source_promoted':'Wrong source identity promoted','correct_accepted_but_identity_conflict':'Correct acceptance blocked by source-identity conflict','correct_source_never_candidate':'Correct source never entered candidate pool','never_queried_input_length':'Never queried: function exceeds input limit','never_queried_no_available_source_candidate':'Never queried: no available source candidates','never_queried_other':'Never queried: other condition','correct_accepted_other':'Correct acceptance blocked: other condition'}
summary={'created':datetime.now(timezone.utc).isoformat(),'status':'complete','promptVersion':'jquery-pilot-v8-short-mapping-verdict-only','builds':comparisons,'pooledOccurrences':{'supported':known,'correct':correct,'recoveryPercent':100*correct/known,'previousCorrect':before,'previousRecoveryPercent':100*before/known,'wrong':wrong,'identityPrecisionPercent':100*correct/(correct+wrong),'notCorrect':known-correct},'nonRecoveryReasons':breakdown['aggregate'],'previousNonRecoveryReasons':oldBreakdown['aggregate'],'verification':{k:verify[k] for k in ['status','checks','uniqueValidatorRequests','requestsWithThinkingContent']},'scope':'Source-map identity recovery on one pinned jQuery version and three correlated builds. Source mapping does not prove unrestricted semantic equivalence. Unassessed predictions are separate; non-recovery categories are mutually exclusive observed barriers, not causal intervention estimates.'}
(P/'comparison-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
md='# Full v8 experiment: recovery and remaining barriers\n\n'+summary['scope']+'\n\nActive validator: **compact variable mapping + verdict only, thinking off**. Minification on and tree shaking off for esbuild, Rollup and webpack. The initial anchors, fixtures, static graph, ranking, top-three policy, uniqueness and conflict rules match the historical baseline; prompt changes can alter later candidate pools.\n\n## Recovery\n\n| Build | Correct / supported | Recovery | Historical recovery | Wrong final identities | Unassessed predictions | Identity precision |\n|---|---:|---:|---:|---:|---:|---:|\n'
for b in comparisons:md+=f'| {b["build"]} | {b["correct"]}/{b["supportedFunctions"]} | {b["recoveryPercent"]:.2f}% | {b["previousCorrect"]}/{b["supportedFunctions"]} ({b["previousRecoveryPercent"]:.2f}%) | {b["wrong"]} | {b["unassessed"]} | {b["identityPrecisionPercent"]:.2f}% |\n'
md+=f'\nDescriptive pooled build occurrences: {correct}/{known} correctly recovered ({100*correct/known:.2f}%), compared with {before}/{known} ({100*before/known:.2f}%). Builds and repeated source functions are correlated; this pooling is not a count of independent functions or trials.\n\n'
md+='## Why the remaining supported functions were not correctly recovered\n\nWrong final identities are included as not correctly recovered. Unassessed bundle definitions are outside this denominator. Category precedence is documented in the per-function audit.\n\n| Observed barrier | esbuild | Rollup | webpack | Total | % of remaining | Historical total |\n|---|---:|---:|---:|---:|---:|---:|\n'
bs={b['build']:b['categories'] for b in breakdown['builds']}
for reason,count in sorted(breakdown['aggregate'].items(),key=lambda kv:-kv[1]):md+='| '+names.get(reason,reason)+' | '+' | '.join(str(bs[b['build']].get(reason,0)) for b in comparisons)+f' | {count} | {100*count/(known-correct):.2f}% | {oldBreakdown["aggregate"].get(reason,0)} |\n'
md+='| **Total not correctly recovered** | '+' | '.join(str(b['supportedFunctions']-b['correct']) for b in comparisons)+f' | **{known-correct}** | **100%** | {known-before} |\n'
md+='\n## Interpretation\n\nCorrect top-three candidates that were never accepted decreased from '+str(oldBreakdown['aggregate'].get('correct_top3_but_never_accepted',0))+' to '+str(breakdown['aggregate'].get('correct_top3_but_never_accepted',0))+'. Multiple accepted candidates now block '+str(breakdown['aggregate'].get('correct_accepted_but_multiple_positives',0))+' targets, compared with '+str(oldBreakdown['aggregate'].get('correct_accepted_but_multiple_positives',0))+' previously. Wrong final identities increased from '+str(sum(b['final']['wrong'] for b in old['builds']))+' to '+str(wrong)+'. The main observed barrier has shifted toward ambiguous acceptance. The promotion policy still requires exactly one accepted candidate; this experiment does not test accepting the first positive candidate. Pair-level precision is reported separately in REPORT.md and must not be inferred from final-match precision.\n'
md+='\n## Verification and provenance\n\n'
md+=f'Mechanical verification: {verify["status"]}; {verify["checks"]} checks; {verify["uniqueValidatorRequests"]} distinct validation requests referenced; {verify["requestsWithThinkingContent"]} with returned thinking content. Full requests, mappings, verdicts, ranks and round dependencies are retained. The input-provenance manifest lists imported exact-request judgments and unchanged embeddings; cached outputs are not new independent inferences. Invalid/error responses remain explicit. No semantic-equivalence proof or zero-false-positive guarantee is claimed.\n\n'
md+='[Main experimental report](REPORT.md), [unrecovered functions and code](recovery-bottlenecks/REPORT.md), [per-function reason records](recovery-bottlenecks/summary.json), [verification](verification.json), [input and cache provenance](input-provenance.json), [machine-readable comparison](comparison-summary.json).\n'
(P/'COMPARISON.md').write_text(md)
print(json.dumps(summary,indent=2))
